Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    steps.forEachIndexed { index, step ->
        val channel = channelOf(step.channel)
        val update = { changed: Step -> steps = steps.map { if (it.id == changed.id) changed else it } }
        MonarchCard {
            Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Column(modifier = Modifier.weight(1f)) {
                        MonarchText(
                            text = "Step ${index + 1}, ${channel.label}",
                            style = MonarchTextStyle.Subheading,
                            modifier = Modifier.semantics { heading() },
                        )
                        MonarchText(text = whenSent(step.waitMinutes), style = MonarchTextStyle.Caption)
                    }
                    MonarchIconButton(label = "Remove step ${index + 1}", onClick = { steps = steps.filterNot { it.id == step.id } }) {
                        MonarchIcon(SampleIcons.Close, contentDescription = null)
                    }
                    MonarchIconButton(
                        label = "Move step ${index + 1} up",
                        onClick = { steps = steps.toMutableList().also { java.util.Collections.swap(it, index, index - 1) } },
                        enabled = index > 0,
                    ) { MonarchIcon(SampleIcons.ChevronUp, contentDescription = null) }
                    MonarchIconButton(
                        label = "Move step ${index + 1} down",
                        onClick = { steps = steps.toMutableList().also { java.util.Collections.swap(it, index, index + 1) } },
                        enabled = index < steps.size - 1,
                    ) { MonarchIcon(SampleIcons.ChevronDown, contentDescription = null) }
                }
                MonarchDurationInput(
                    minutes = step.waitMinutes,
                    onMinutesChange = { update(Step(step.id, step.channel, it, step.subject, step.body)) },
                    label = "Wait before sending",
                    helperText = "For example 2d, 4h or 30m.",
                    largestUnit = MonarchDurationInputUnit.Days,
                )
                if (channel.hasSubject) {
                    MonarchTextField(
                        value = step.subject,
                        onValueChange = { update(Step(step.id, step.channel, step.waitMinutes, it, step.body)) },
                        label = "Subject",
                        required = true,
                    )
                }
                MonarchTextField(
                    value = step.body,
                    onValueChange = { update(Step(step.id, step.channel, step.waitMinutes, step.subject, it)) },
                    label = "Message",
                    required = true,
                    singleLine = false,
                    minLines = 3,
                )
                channel.maxLength?.let {
                    MonarchText(text = "${step.body.length} / $it", style = MonarchTextStyle.Caption)
                }
                MonarchText(text = "Insert a variable", style = MonarchTextStyle.Caption)
                FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                    variables.forEach { variable ->
                        MonarchButton(
                            text = variable.label,
                            onClick = { update(Step(step.id, step.channel, step.waitMinutes, step.subject, step.body + "{{" + variable.token + "}}")) },
                            variant = MonarchButtonVariant.Secondary,
                            size = MonarchButtonSize.Sm,
                        )
                    }
                }
                MonarchCollapsible(
                    expanded = step.id in previews,
                    onExpandedChange = { open -> previews = if (open) previews + step.id else previews - step.id },
                    label = "Preview with sample data",
                ) {
                    if (channel.hasSubject) {
                        MonarchText(text = render(step.subject), style = MonarchTextStyle.BodyStrong)
                    }
                    MonarchText(text = render(step.body))
                }
            }
        }
    }
    FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        channels.forEach { option ->
            MonarchButton(
                text = "Add ${option.label} step",
                leadingIcon = { MonarchIcon(SampleIcons.Plus, null) },
                onClick = { steps = steps + Step((steps.size + 1).toString(), option.key, 1_440, "", "") },
                variant = MonarchButtonVariant.Secondary,
                size = MonarchButtonSize.Sm,
            )
        }
    }
}

