class Step(val id: String, val channel: String, val waitMinutes: Int?, val subject: String, val body: String)
class Channel(val key: String, val label: String, val hasSubject: Boolean, val maxLength: Int?)
class Variable(val token: String, val label: String, val sample: String)
val channels = listOf(
    Channel({{channels.0.value}}, {{channels.0.label}}, hasSubject = {{channels.0.hasSubject}}, maxLength = null),
    Channel({{channels.1.value}}, {{channels.1.label}}, hasSubject = false, maxLength = {{channels.1.maxLength}}),
)
val variables = listOf(
    Variable({{variables.0.token}}, {{variables.0.label}}, {{variables.0.sample}}),
    Variable({{variables.1.token}}, {{variables.1.label}}, {{variables.1.sample}}),
    Variable({{variables.2.token}}, {{variables.2.label}}, {{variables.2.sample}}),
)
fun channelOf(key: String) = channels.firstOrNull { it.key == key } ?: channels.first()
fun render(text: String) = variables.fold(text) { acc, v -> acc.replace("{{" + v.token + "}}", v.sample) }
fun whenSent(minutes: Int?): String = when {
    (minutes ?: 0) == 0 -> "Sent straight away"
    minutes!! % 1_440 == 0 -> "Sent ${minutes / 1_440}d after the previous step"
    minutes % 60 == 0 -> "Sent ${minutes / 60}h after the previous step"
    else -> "Sent ${minutes}m after the previous step"
}
var steps by remember {
    mutableStateOf(
        listOf(
            Step("1", {{steps.0.channel}}, {{steps.0.delayMinutes}}, {{steps.0.subject}}, {{steps.0.body}}),
            Step("2", {{steps.1.channel}}, {{steps.1.delayMinutes}}, "", {{steps.1.body}}),
        ),
    )
}
var previews by remember { mutableStateOf(emptySet<String>()) }

